variable "name" {
  description = "DB identifier (becomes RDS instance ID and secret prefix)"
  type        = string
}

variable "env" {
  description = "Environment: dev | staging | prod (affects deletion protection, backup retention)"
  type        = string
}

variable "engine_version" {
  description = "Postgres engine version"
  type        = string
  default     = "16.4"
}

variable "instance_class" {
  description = "RDS instance class"
  type        = string
  default     = "db.t4g.small"
}

variable "allocated_storage" {
  description = "Initial allocated storage (GB)"
  type        = number
  default     = 50
}

variable "max_allocated_storage" {
  description = "Storage autoscaling cap (GB). Set to 0 to disable."
  type        = number
  default     = 500
}

variable "db_name" {
  description = "Initial database name"
  type        = string
  default     = "app"
}

variable "master_username" {
  description = "Master username (rotated independently)"
  type        = string
  default     = "appadmin"
}

variable "multi_az" {
  description = "Multi-AZ deployment (true in prod)"
  type        = bool
  default     = false
}

variable "backup_retention_days" {
  description = "PITR / automated backup retention"
  type        = number
  default     = 14
}

variable "subnet_ids" {
  description = "Private subnet IDs"
  type        = list(string)
}

variable "vpc_security_group_ids" {
  description = "Security groups allowed to reach the DB"
  type        = list(string)
}

variable "kms_key_arn" {
  description = "KMS key for storage encryption (null = AWS-managed)"
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags applied to every resource"
  type        = map(string)
  default     = {}
}

# RDS Postgres with: encrypted storage, PITR, Multi-AZ option, parameter group
# tuned for app workloads, secret stored in Secrets Manager for app injection.

terraform {
  required_version = ">= 1.9.0"
  required_providers {
    aws    = { source = "hashicorp/aws", version = "~> 5.60" }
    random = { source = "hashicorp/random", version = "~> 3.6" }
  }
}

resource "random_password" "master" {
  length           = 32
  special          = true
  override_special = "!#$%^&*()-_=+[]{}<>:?"
}

resource "aws_db_subnet_group" "this" {
  name        = "${var.name}-db-subnets"
  description = "DB subnet group for ${var.name}"
  subnet_ids  = var.subnet_ids
  tags        = var.tags
}

resource "aws_db_parameter_group" "this" {
  name        = "${var.name}-pg16"
  family      = "postgres16"
  description = "App-tuned Postgres parameters"

  parameter { name = "log_min_duration_statement", value = "500" }
  parameter { name = "shared_preload_libraries",   value = "pg_stat_statements", apply_method = "pending-reboot" }
}

resource "aws_db_instance" "this" {
  identifier              = var.name
  engine                  = "postgres"
  engine_version          = var.engine_version
  instance_class          = var.instance_class
  allocated_storage       = var.allocated_storage
  max_allocated_storage   = var.max_allocated_storage
  storage_type            = "gp3"
  storage_encrypted       = true
  kms_key_id              = var.kms_key_arn
  db_name                 = var.db_name
  username                = var.master_username
  password                = random_password.master.result
  port                    = 5432
  publicly_accessible     = false
  multi_az                = var.multi_az
  db_subnet_group_name    = aws_db_subnet_group.this.name
  vpc_security_group_ids  = var.vpc_security_group_ids
  parameter_group_name    = aws_db_parameter_group.this.name
  backup_retention_period = var.backup_retention_days
  backup_window           = "03:00-04:00"
  maintenance_window      = "Mon:04:00-Mon:05:00"
  copy_tags_to_snapshot   = true
  deletion_protection     = var.env == "prod"
  skip_final_snapshot     = var.env != "prod"
  final_snapshot_identifier = var.env == "prod" ? "${var.name}-final-${formatdate("YYYYMMDDhhmm", timestamp())}" : null
  performance_insights_enabled = true
  enabled_cloudwatch_logs_exports = ["postgresql"]
  apply_immediately      = var.env != "prod"
  tags = var.tags

  lifecycle { ignore_changes = [final_snapshot_identifier] }
}

resource "aws_secretsmanager_secret" "connection" {
  name                    = "${var.name}/connection"
  description             = "DATABASE_URL for ${var.name}"
  recovery_window_in_days = var.env == "prod" ? 7 : 0
  tags                    = var.tags
}

resource "aws_secretsmanager_secret_version" "connection" {
  secret_id     = aws_secretsmanager_secret.connection.id
  secret_string = "postgresql+asyncpg://${var.master_username}:${urlencode(random_password.master.result)}@${aws_db_instance.this.address}:5432/${var.db_name}"
}

output "endpoint" {
  description = "RDS endpoint host"
  value       = aws_db_instance.this.address
}

output "port" {
  description = "RDS endpoint port"
  value       = aws_db_instance.this.port
}

output "db_name" {
  description = "Initial database name"
  value       = aws_db_instance.this.db_name
}

output "connection_secret_arn" {
  description = "Secrets Manager ARN holding the full DATABASE_URL"
  value       = aws_secretsmanager_secret.connection.arn
}

output "connection_secret_name" {
  description = "Secrets Manager secret name"
  value       = aws_secretsmanager_secret.connection.name
}

variable "name" {
  description = "Service name (also used as task family + log group key)"
  type        = string
}

variable "env" {
  description = "Environment name: dev | staging | prod"
  type        = string
}

variable "cluster_arn" {
  description = "ARN of the ECS cluster"
  type        = string
}

variable "container_image" {
  description = "Container image URI including tag/digest"
  type        = string
}

variable "container_port" {
  description = "Port the container listens on"
  type        = number
  default     = 8000
}

variable "health_path" {
  description = "HTTP path for in-container health check"
  type        = string
  default     = "/health"
}

variable "cpu" {
  description = "Fargate task CPU units (256, 512, 1024, ...)"
  type        = number
  default     = 512
}

variable "memory" {
  description = "Fargate task memory in MB"
  type        = number
  default     = 1024
}

variable "desired_count" {
  description = "Number of desired tasks"
  type        = number
  default     = 2
}

variable "env_vars" {
  description = "Plain environment variables (use secret_arns for sensitive values)"
  type        = map(string)
  default     = {}
}

variable "secret_arns" {
  description = "Map of env-var name -> Secrets Manager / SSM Parameter ARN"
  type        = map(string)
  default     = {}
}

variable "subnet_ids" {
  description = "Private subnet IDs for the task ENIs"
  type        = list(string)
}

variable "security_group_ids" {
  description = "Security group IDs attached to the task ENIs"
  type        = list(string)
}

variable "target_group_arn" {
  description = "Optional ALB target group ARN to register tasks with"
  type        = string
  default     = null
}

variable "log_retention_days" {
  description = "CloudWatch log group retention"
  type        = number
  default     = 30
}

variable "tags" {
  description = "Tags applied to every resource"
  type        = map(string)
  default     = {}
}

output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.this.id
}

output "public_subnet_ids" {
  description = "IDs of public subnets, one per AZ"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of private subnets, one per AZ"
  value       = aws_subnet.private[*].id
}

output "app_sg_id" {
  description = "Security group for application tier"
  value       = aws_security_group.app.id
}

output "db_sg_id" {
  description = "Security group for database tier (accepts traffic from app SG only)"
  value       = aws_security_group.db.id
}

variable "name" {
  description = "Project + environment name prefix (e.g. softco-dev)"
  type        = string
}

variable "cidr" {
  description = "VPC CIDR block"
  type        = string
  default     = "10.10.0.0/16"
}

variable "az_count" {
  description = "Number of availability zones (and matching public/private subnets)"
  type        = number
  default     = 3
}

variable "ha_nat" {
  description = "If true, one NAT gateway per AZ (prod). If false, one shared NAT (dev/staging)."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags applied to every resource"
  type        = map(string)
  default     = {}
}

output "service_arn" {
  description = "ECS service ARN"
  value       = aws_ecs_service.this.id
}

output "task_role_arn" {
  description = "IAM role assumed by the running container (use for app permissions)"
  value       = aws_iam_role.task.arn
}

output "task_definition_arn" {
  description = "Active task definition ARN"
  value       = aws_ecs_task_definition.this.arn
}

output "log_group_name" {
  description = "CloudWatch log group name"
  value       = aws_cloudwatch_log_group.this.name
}
